1	package cli
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"log/slog"
11		"os"
12		"path/filepath"
13		"strings"
14		"time"
15	
16		"github.com/entireio/cli/cmd/entire/cli/internal/flock"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/internal/entireclient/userdirs"
19	)
20	
21	// Plugin discovery rides on a git-synced index, krew-style: the index is
22	// itself a git repository containing index.json, shallow-cloned into the
23	// user cache and re-pulled on a TTL. No hosted service, no forge REST API —
24	// any git server can host an index, and a repo can point contributors at an
25	// internal catalog via plugins.index_url in .entire/settings.json.
26	const (
27		// defaultPluginIndexURL is the built-in curated index.
28		defaultPluginIndexURL = "https://github.com/entireio/plugin-index"
29		// pluginIndexEnvVar overrides the index URL (forwarded to plugin
30		// children automatically via the ENTIRE_ allowlist prefix).
31		pluginIndexEnvVar = "ENTIRE_PLUGIN_INDEX_URL"
32		// pluginIndexFileName is the catalog file at the index repo root.
33		pluginIndexFileName = "index.json"
34		// pluginIndexSchemaVersion is the index schema this CLI reads. Advisory:
35		// a higher declared version logs a warning and is still read (see
36		// loadPluginIndexFromDir).
37		pluginIndexSchemaVersion = 1
38		// pluginIndexSyncMarker records the last successful sync time as the
39		// marker file's mtime. Untracked, so fetch/reset never touches it.
40		pluginIndexSyncMarker = ".entire-last-sync"
41	)
42	
43	// PluginIndex is the parsed catalog. Decoding is deliberately lenient
44	// (unknown fields ignored) so an index that grows new fields doesn't break
45	// older CLI versions fleet-wide.
46	type PluginIndex struct {
47		// Version is the declared schema version. Advisory only — see
48		// loadPluginIndexFromDir for why it isn't enforced.
49		Version int                `json:"version"`
50		Plugins []PluginIndexEntry `json:"plugins"`
51	}
52	
53	// PluginIndexEntry describes one plugin in the catalog.
54	type PluginIndexEntry struct {
55		Name        string `json:"name"`
56		RepoURL     string `json:"repo_url"`
57		Description string `json:"description,omitempty"`
58		Official    bool   `json:"official,omitempty"`
59		// Platforms lists supported GOOS values when the plugin doesn't ship
60		// the full matrix; empty means all.
61		Platforms []string `json:"platforms,omitempty"`
62	}
63	
64	// Find returns the entry with the given bare name, or nil.
65	func (idx *PluginIndex) Find(name string) *PluginIndexEntry {
66		if idx == nil {
67			return nil
68		}
69		for i := range idx.Plugins {
70			if idx.Plugins[i].Name == name {
71				return &idx.Plugins[i]
72			}
73		}
74		return nil
75	}
76	
77	// Search returns entries whose name or description contains term
78	// (case-insensitive). An empty term returns everything.
79	func (idx *PluginIndex) Search(term string) []PluginIndexEntry {
80		if idx == nil {
81			return nil
82		}
83		if term == "" {
84			return idx.Plugins
85		}
86		t := strings.ToLower(term)
87		var out []PluginIndexEntry
88		for _, e := range idx.Plugins {
89			if strings.Contains(strings.ToLower(e.Name), t) || strings.Contains(strings.ToLower(e.Description), t) {
90				out = append(out, e)
91			}
92		}
93		return out
94	}
95	
96	// HasRepoURL reports whether a repo URL is listed in the index — the trust
97	// check for install confirmations. Compared with the .git suffix and
98	// trailing slashes normalized.
99	func (idx *PluginIndex) HasRepoURL(repoURL string) bool {
100		if idx == nil {
101			return false
102		}
103		want := normalizeRepoURL(repoURL)
104		for _, e := range idx.Plugins {
105			if normalizeRepoURL(e.RepoURL) == want {
106				return true
107			}
108		}
109		return false
110	}
111	
112	func normalizeRepoURL(u string) string {
113		return strings.TrimSuffix(strings.TrimRight(strings.TrimSpace(u), "/"), ".git")
114	}
115	
116	// resolvePluginIndexURL applies the documented precedence: --index flag >
117	// ENTIRE_PLUGIN_INDEX_URL > settings (local over project) > built-in
118	// default. Settings load failures fall through to the default rather than
119	// blocking discovery; the failure is logged at debug.
120	func resolvePluginIndexURL(ctx context.Context, flagValue string) string {
121		if flagValue != "" {
122			return flagValue
123		}
124		if v := os.Getenv(pluginIndexEnvVar); v != "" {
125			return v
126		}
127		s, err := LoadEntireSettings(ctx)
128		if err != nil {
129			logging.Debug(ctx, "plugin index: settings load failed, using default index", slog.String("error", err.Error()))
130			return defaultPluginIndexURL
131		}
132		if u := s.PluginIndexURL(); u != "" {
133			return u
134		}
135		return defaultPluginIndexURL
136	}
137	
138	// pluginIndexTTL returns the freshness window from settings (default 24h).
139	func pluginIndexTTL(ctx context.Context) time.Duration {
140		s, err := LoadEntireSettings(ctx)
141		if err != nil {
142			return 24 * time.Hour
143		}
144		return s.PluginIndexTTL()
145	}
146	
147	// pluginIndexCacheDir is the per-URL local copy. Keyed by a hash of the
148	// URL so switching indexes (or per-repo overrides) never serves one
149	// catalog's cache for another.
150	func pluginIndexCacheDir(indexURL string) (string, error) {
151		cache := userdirs.Cache()
152		if cache == "" {
153			return "", errors.New("cannot resolve user cache directory")
154		}
155		sum := sha256.Sum256([]byte(normalizeRepoURL(indexURL)))
156		return filepath.Join(cache, "plugin-index", hex.EncodeToString(sum[:6])), nil
157	}
158	
159	// SyncPluginIndex returns the catalog for indexURL, cloning or refreshing
160	// the local copy as needed. force bypasses the TTL. When a refresh fails
161	// but a previous copy exists, the stale copy is used with a warning logged
162	// — discovery shouldn't hard-fail because a laptop is offline.
163	func SyncPluginIndex(ctx context.Context, indexURL string, force bool) (*PluginIndex, error) {
164		// The index URL reaches `git clone` as a positional; it can come from
165		// --index or ENTIRE_PLUGIN_INDEX_URL, neither of which the settings
166		// validator sees. Reject non-URLs before git can read one as an option.
167		if err := validatePluginRepoURL(indexURL); err != nil {
168			return nil, fmt.Errorf("plugin index URL: %w", err)
169		}
170		dir, err := pluginIndexCacheDir(indexURL)
171		if err != nil {
172			return nil, err
173		}
174	
175		// The cache dir is shared by every concurrent `entire plugin` invocation
176		// and syncing it is destructive: RemoveAll + clone on the cold path,
177		// fetch + `reset --hard FETCH_HEAD` on the warm one. Serialize the whole
178		// sync-and-read under an advisory lock, the same way discovery/cache.go
179		// guards its shared cache files. Without it, one process cloning while
180		// another reads index.json surfaces a spurious "no readable index.json",
181		// and two cold syncs racing can leave exactly the half-created directory
182		// the sweep below exists to recover from.
183		//
184		// The lock file is a *sibling* of the cache dir, not inside it: RemoveAll
185		// on the dir would otherwise delete the lock file while we hold it.
186		if err := os.MkdirAll(filepath.Dir(dir), 0o750); err != nil {
187			return nil, fmt.Errorf("create index cache dir: %w", err)
188		}
189		release, err := flock.AcquireContext(ctx, dir+".lock")
190		if err != nil {
191			return nil, fmt.Errorf("lock plugin index cache: %w", err)
192		}
193		defer release()
194	
195		marker := filepath.Join(dir, pluginIndexSyncMarker)
196		_, statErr := os.Stat(filepath.Join(dir, ".git"))
197		cloned := statErr == nil
198	
199		fresh := false
200		if cloned && !force {
201			if info, err := os.Stat(marker); err == nil {
202				// A negative age means the marker is dated in the future (clock
203				// rollback, restored backup, bad container clock). Treating that as
204				// fresh would freeze the catalog until someone ran `index update`
205				// by hand, so only a non-negative age inside the window counts.
206				if age := time.Since(info.ModTime()); age >= 0 && age < pluginIndexTTL(ctx) {
207					fresh = true
208				}
209			}
210		}
211	
212		switch {
213		case !cloned:
214			// A previously interrupted clone can leave a partial directory
215			// without .git. git refuses to clone into a non-empty target, so
216			// without this sweep, discovery would stay wedged until the user
217			// cleared the cache by hand.
218			if err := os.RemoveAll(dir); err != nil {
219				return nil, fmt.Errorf("clear stale index cache: %w", err)
220			}
221			if _, err := runGitQuiet(ctx, "clone", "--depth", "1", "--quiet", "--", indexURL, dir); err != nil {
222				return nil, fmt.Errorf("clone plugin index %s: %w%s", redactURL(indexURL), err, stderrSuffix(err))
223			}
224			touchFile(marker)
225		case !fresh:
226			if err := refreshPluginIndexClone(ctx, dir); err != nil {
227				logging.Warn(ctx, "plugin index refresh failed; using cached copy",
228					slog.String("index", redactURL(indexURL)), slog.String("error", err.Error()))
229			} else {
230				touchFile(marker)
231			}
232		}
233	
234		return loadPluginIndexFromDir(ctx, dir, indexURL)
235	}
236	
237	// refreshPluginIndexClone updates an existing shallow clone to the remote
238	// tip regardless of the remote's default branch name.
239	func refreshPluginIndexClone(ctx context.Context, dir string) error {
240		if _, err := runGitQuiet(ctx, "-C", dir, "fetch", "--depth", "1", "--quiet", "origin", "HEAD"); err != nil {
241			return fmt.Errorf("fetch: %w%s", err, stderrSuffix(err))
242		}
243		if _, err := runGitQuiet(ctx, "-C", dir, "reset", "--hard", "--quiet", "FETCH_HEAD"); err != nil {
244			return fmt.Errorf("reset: %w%s", err, stderrSuffix(err))
245		}
246		return nil
247	}
248	
249	func touchFile(path string) {
250		now := time.Now()
251		if err := os.Chtimes(path, now, now); err == nil {
252			return
253		}
254		if f, err := os.Create(path); err == nil { //nolint:gosec // marker file inside our cache dir
255			_ = f.Close()
256		}
257	}
258	
259	func loadPluginIndexFromDir(ctx context.Context, dir, indexURL string) (*PluginIndex, error) {
260		data, err := os.ReadFile(filepath.Join(dir, pluginIndexFileName)) //nolint:gosec // file inside our cache dir
261		if err != nil {
262			return nil, fmt.Errorf("plugin index %s has no readable %s: %w", redactURL(indexURL), pluginIndexFileName, err)
263		}
264		var idx PluginIndex
265		if err := json.Unmarshal(data, &idx); err != nil {
266			return nil, fmt.Errorf("parse %s from %s: %w", pluginIndexFileName, redactURL(indexURL), err)
267		}
268		// version is recorded, not enforced. Refusing an unrecognized value would
269		// protect against a migration that can never happen: the index is one
270		// shared resource read by every CLI version ever shipped, so bumping it
271		// would break discovery fleet-wide with no gradual rollout and no undo for
272		// installed binaries. An incompatible schema therefore ships at a new path
273		// (index-v2.json, another branch, another repo), which needs no gate here.
274		// Enforcing it only ever fired by accident — most painfully on an index
275		// that simply omits the field (version 0), which told the author to
276		// upgrade the CLI when the fix was in their own file. Hand-written
277		// internal catalogs are exactly what plugins.index_url exists for.
278		//
279		// Additive changes, the ones that actually happen, are already absorbed:
280		// decoding ignores unknown fields and unreadable entries are dropped
281		// below. Degrading per entry beats refusing the catalog.
282		if idx.Version > pluginIndexSchemaVersion {
283			logging.Warn(ctx, "plugin index declares a newer schema version; reading what this CLI understands",
284				slog.String("index", redactURL(indexURL)),
285				slog.Int("declared_version", idx.Version),
286				slog.Int("understood_version", pluginIndexSchemaVersion))
287		}
288		var valid []PluginIndexEntry
289		for _, e := range idx.Plugins {
290			// repo_url is validated here, not just at the git boundary: an
291			// index-resolved install is treated as trusted and never prompts, so
292			// a hostile catalog entry must not reach the git CLI at all.
293			if validatePluginName(e.Name) != nil || validatePluginRepoURL(e.RepoURL) != nil {
294				continue // tolerate bad entries rather than failing the catalog
295			}
296			valid = append(valid, e)
297		}
298		idx.Plugins = valid
299		return &idx, nil
300	}
301

