1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"os/exec"
7		"path/filepath"
8		"runtime"
9		"slices"
10		"strings"
11	
12		"golang.org/x/mod/semver"
13	)
14	
15	// Dependency handling is install-time only. Dispatch stays zero-cost: a
16	// plugin invokes its deps as entire-<dep> via PATH at runtime (the managed
17	// bin dir is prepended for plugin children), and `entire plugin doctor`
18	// reports drift after the fact. There is deliberately no version-range
19	// solver — requirements carry at most a minimum version.
20	
21	// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
22	// practice; the bound turns a metadata cycle that slips past the visited
23	// set (e.g. two names aliasing one repo) into an error instead of a hang.
24	const maxDepDepth = 10
25	
26	// DepAction is one planned dependency install or upgrade.
27	type DepAction struct {
28		Name       string
29		RepoURL    string
30		MinVersion string
31		// Upgrade is true when the dependency is installed but below
32		// MinVersion; the action reinstalls at the latest tag.
33		Upgrade bool
34		// CurrentTag is the installed tag for upgrades.
35		CurrentTag string
36		// FromIndex is true when the repo URL came from the index (trusted)
37		// rather than from another plugin's metadata.
38		FromIndex bool
39	}
40	
41	// DepPlan is the result of resolving a plugin's transitive requirements.
42	type DepPlan struct {
43		Actions []DepAction
44		// Warnings are non-blocking observations, e.g. a dependency satisfied
45		// from raw $PATH whose version cannot be verified.
46		Warnings []string
47	}
48	
49	// PlanDependencyInstalls resolves the transitive requirements of rootReqs
50	// into ordered install/upgrade actions. Missing dependencies must be
51	// resolvable to a repo URL via the requirement itself or the index. The
52	// visited set plus a depth bound make cycles an error path, not a hang.
53	func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
54		plan := &DepPlan{}
55		// name -> strictest min_version considered so far, not a plain seen-set:
56		// see planDeps.
57		considered := map[string]string{}
58		if err := planDeps(ctx, rootReqs, idx, plan, considered, 0); err != nil {
59			return nil, err
60		}
61		return plan, nil
62	}
63	
64	// stricterMinVersion reports whether a demands a higher minimum than b.
65	// An empty string means "no minimum": nothing is stricter than it, and any
66	// concrete minimum is stricter than it.
67	func stricterMinVersion(a, b string) bool {
68		switch {
69		case a == "":
70			return false
71		case b == "":
72			return true
73		default:
74			return semver.Compare(canonicalSemver(a), canonicalSemver(b)) > 0
75		}
76	}
77	
78	// upsertDepAction keeps one action per plugin name, replacing an earlier
79	// entry when a stricter requirement supersedes it.
80	func upsertDepAction(plan *DepPlan, action DepAction) {
81		for i := range plan.Actions {
82			if plan.Actions[i].Name == action.Name {
83				plan.Actions[i] = action
84				return
85			}
86		}
87		plan.Actions = append(plan.Actions, action)
88	}
89	
90	// addDepWarning appends a warning unless it is already present. Re-visiting a
91	// name under a stricter constraint can re-derive the same observation, and
92	// printing it twice would just look like a bug.
93	func addDepWarning(plan *DepPlan, warning string) {
94		if warning == "" || slices.Contains(plan.Warnings, warning) {
95			return
96		}
97		plan.Warnings = append(plan.Warnings, warning)
98	}
99	
100	func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, considered map[string]string, depth int) error {
101		if depth > maxDepDepth {
102			return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
103		}
104		for _, req := range reqs {
105			// Keyed by name *and* gated on the strictest min_version seen so far,
106			// not a plain seen-set. In a diamond where two requirers demand
107			// different minimums of the same plugin (A needs C >= v1, B needs
108			// C >= v2), a name-only set skipped B's stricter constraint entirely:
109			// an installed C satisfying v1 produced no action and no warning, so
110			// the install completed leaving B running against a too-old C. Doctor
111			// caught it afterwards — it walks each manifest's requirements
112			// independently — but the install should plan the upgrade, not defer
113			// the discovery.
114			if prev, seen := considered[req.Name]; seen && !stricterMinVersion(req.MinVersion, prev) {
115				continue
116			}
117			// Past the guard this name is either new or strictly stricter than
118			// what was recorded, so this requirement's minimum is the one to keep.
119			considered[req.Name] = req.MinVersion
120	
121			satisfied, warning, err := dependencySatisfied(req)
122			if err != nil {
123				return err
124			}
125			addDepWarning(plan, warning)
126			if satisfied {
127				// An already-satisfied managed dependency can itself have
128				// gaps (e.g. its own dep was removed with --force since
129				// install). Walk its recorded requirements — offline, from
130				// the manifest — so installing a parent repairs the whole
131				// chain instead of stopping at the first satisfied node.
132				// PATH/local-dev installs have no manifest; doctor covers
133				// those.
134				m, err := LoadPluginManifest(req.Name)
135				if err != nil {
136					return err
137				}
138				if m != nil {
139					if err := planDeps(ctx, m.Requires, idx, plan, considered, depth+1); err != nil {
140						return err
141					}
142				}
143				continue
144			}
145	
146			m, err := LoadPluginManifest(req.Name)
147			if err != nil {
148				return err
149			}
150			action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
151			if m != nil {
152				// Installed but below min_version: upgrade in place from its
153				// recorded repo.
154				action.Upgrade = true
155				action.CurrentTag = m.Tag
156				action.RepoURL = m.RepoURL
157			} else {
158				action.RepoURL = req.RepoURL
159				if action.RepoURL == "" {
160					if e := idx.Find(req.Name); e != nil {
161						action.RepoURL = e.RepoURL
162					}
163				}
164				if action.RepoURL == "" {
165					return fmt.Errorf("dependency %q is not installed and has no repo URL (not in the plugin index either); add repo_url to the requirement or install it manually", req.Name)
166				}
167			}
168			// Set uniformly from the resolved URL rather than only on the branches
169			// that consulted the index, so the flag means one thing everywhere:
170			// "this URL is listed in the catalog". The command layer surfaces the
171			// ones that aren't before asking for confirmation — a dependency's
172			// repo_url is author-controlled, so it deserves the same visibility as
173			// a URL the user typed. A nil index (offline during a URL install)
174			// makes everything unlisted, which is the conservative answer.
175			action.FromIndex = idx.HasRepoURL(action.RepoURL)
176			upsertDepAction(plan, action)
177	
178			// Recurse into what the dependency itself requires, using metadata
179			// only — nothing is downloaded during planning. Inspection
180			// failures don't fail the plan (the install will surface hard
181			// errors itself), but they must not be silent either: a confirmed
182			// plan that quietly omitted nested dependencies would look
183			// complete while leaving gaps for doctor to find.
184			tag := ""
185			if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
186				tag = tags[0]
187			}
188			if tag == "" {
189				addDepWarning(plan, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, action.RepoURL))
190				continue
191			}
192			meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
193			if err != nil {
194				addDepWarning(plan, fmt.Sprintf("could not read %s for %q at %s; its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", pluginMetadataFileName, req.Name, tag))
195				continue
196			}
197			if meta == nil {
198				continue // no metadata file: no declared dependencies
199			}
200			if err := planDeps(ctx, meta.Requires, idx, plan, considered, depth+1); err != nil {
201				return err
202			}
203		}
204		return nil
205	}
206	
207	// dependencySatisfied checks whether a requirement is already met, in
208	// order: managed install with manifest (version-checkable) → managed entry
209	// without manifest (local-dev, version unknown) → raw $PATH (version
210	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
211	// (main.go restores it for built-ins), so LookPath here sees only
212	// raw-PATH plugins — managed entries are checked explicitly first.
213	func dependencySatisfied(req PluginRequirement) (satisfied bool, warning string, err error) {
214		m, err := LoadPluginManifest(req.Name)
215		if err != nil {
216			return false, "", err
217		}
218		if m != nil {
219			if req.MinVersion == "" || semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0 {
220				return true, "", nil
221			}
222			return false, "", nil // triggers the upgrade path in planDeps
223		}
224		installed, err := FindInstalledPlugin(req.Name)
225		if err != nil {
226			return false, "", err
227		}
228		if installed != nil {
229			return true, unverifiableVersionWarning(req, "a local-dev install"), nil
230		}
231		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
232			return true, unverifiableVersionWarning(req, "$PATH"), nil
233		}
234		return false, "", nil
235	}
236	
237	func unverifiableVersionWarning(req PluginRequirement, source string) string {
238		if req.MinVersion == "" {
239			return ""
240		}
241		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
242	}
243	
244	// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
245	// allowUnverified is inherited from the root install so a single
246	// --allow-unverified covers the whole transitive set the user confirmed,
247	// rather than failing partway through on the first dependency without
248	// published checksums.
249	func ExecuteDepPlan(ctx context.Context, plan *DepPlan, allowUnverified bool) error {
250		for _, a := range plan.Actions {
251			if _, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
252				RepoURL: a.RepoURL, Force: a.Upgrade, AllowUnverified: allowUnverified,
253			}); err != nil {
254				return fmt.Errorf("install dependency %q: %w", a.Name, err)
255			}
256		}
257		return nil
258	}
259	
260	// DependentsOf returns the names of managed plugins whose manifests list
261	// name as a requirement — the remove guard. Computed by scanning
262	// pkg/*/manifest.yml; no extra state to maintain.
263	func DependentsOf(name string) ([]string, error) {
264		manifests, err := ListPluginManifests()
265		if err != nil {
266			return nil, err
267		}
268		var out []string
269		for _, m := range manifests {
270			for _, req := range m.Requires {
271				if req.Name == name {
272					out = append(out, m.Name)
273					break
274				}
275			}
276		}
277		return out, nil
278	}
279	
280	// PluginDoctorIssue is one problem found by RunPluginDoctor.
281	type PluginDoctorIssue struct {
282		Plugin  string
283		Problem string
284		Fix     string
285	}
286	
287	// RunPluginDoctor checks every managed plugin: bin entry present, dangling
288	// local-dev symlinks, dependency presence and min_versions, and (macOS) a
289	// quarantine attribute that would block execution.
290	func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
291		var issues []PluginDoctorIssue
292	
293		installed, err := ListInstalledPlugins()
294		if err != nil {
295			return nil, err
296		}
297		installedByName := map[string]*InstalledPlugin{}
298		for _, p := range installed {
299			installedByName[p.Name] = p
300			if p.Symlink {
301				if _, err := exec.LookPath(p.Path); err != nil {
302					issues = append(issues, PluginDoctorIssue{
303						Plugin:  p.Name,
304						Problem: "managed entry is a dangling or non-executable link to " + p.LinkTarget,
305						Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
306					})
307				}
308			}
309			if q := quarantinedPath(ctx, p.Path); q != "" {
310				issues = append(issues, PluginDoctorIssue{
311					Plugin:  p.Name,
312					Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
313					Fix:     "run: xattr -d com.apple.quarantine " + q,
314				})
315			}
316		}
317	
318		manifests, err := ListPluginManifests()
319		if err != nil {
320			return nil, err
321		}
322		for _, m := range manifests {
323			if installedByName[m.Name] == nil {
324				issues = append(issues, PluginDoctorIssue{
325					Plugin:  m.Name,
326					Problem: "has an install manifest but no entry in the managed bin dir",
327					Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", m.RepoURL),
328				})
329			}
330			issues = append(issues, checkManagedBinaryIntegrity(m)...)
331			for _, req := range m.Requires {
332				satisfied, warning, err := dependencySatisfied(req)
333				if err != nil {
334					return nil, err
335				}
336				switch {
337				case satisfied && warning != "":
338					issues = append(issues, PluginDoctorIssue{Plugin: m.Name, Problem: warning, Fix: ""})
339				case !satisfied:
340					dep, depErr := LoadPluginManifest(req.Name)
341					if depErr != nil {
342						return nil, depErr
343					}
344					if dep != nil {
345						issues = append(issues, PluginDoctorIssue{
346							Plugin:  m.Name,
347							Problem: fmt.Sprintf("requires %s >= %s but %s is installed", req.Name, req.MinVersion, dep.Tag),
348							Fix:     "run: entire plugin upgrade " + req.Name,
349						})
350					} else {
351						issues = append(issues, PluginDoctorIssue{
352							Plugin:  m.Name,
353							Problem: fmt.Sprintf("requires %q, which is not installed", req.Name),
354							Fix:     "run: entire plugin install " + req.Name,
355						})
356					}
357				}
358			}
359		}
360		return issues, nil
361	}
362	
363	// checkManagedBinaryIntegrity re-hashes a managed plugin's binary and
364	// compares it to the digest recorded at install time, catching a binary
365	// swapped out under the managed directory after install.
366	//
367	// This checks the pkg/ binary, which is the copy the manifest describes and
368	// the target bin/ links to. Where the bin/ entry is a copy rather than a link
369	// (Windows without Developer Mode), a tampered copy is not covered — the
370	// dangling/non-executable link check above is what guards that surface.
371	//
372	// A manifest without BinarySHA256 predates integrity recording, so there is
373	// nothing to compare and silence is correct; nagging about it would only tell
374	// the user to reinstall a plugin that is probably fine.
375	func checkManagedBinaryIntegrity(m *PluginManifest) []PluginDoctorIssue {
376		var issues []PluginDoctorIssue
377		if m.Unverified {
378			issues = append(issues, PluginDoctorIssue{
379				Plugin:  m.Name,
380				Problem: fmt.Sprintf("installed from %s without checksum verification (the release published no %s)", m.Tag, checksumsFileName),
381				Fix:     "if the author has since published checksums, re-run: entire plugin upgrade " + m.Name,
382			})
383		}
384		if m.BinarySHA256 == "" {
385			return issues
386		}
387		dir, err := PluginPkgDir(m.Name)
388		if err != nil {
389			return issues
390		}
391		binPath := filepath.Join(dir, pluginBinaryName(m.Name))
392		got, err := fileSHA256(binPath)
393		if err != nil {
394			issues = append(issues, PluginDoctorIssue{
395				Plugin:  m.Name,
396				Problem: "managed binary is missing or unreadable: " + err.Error(),
397				Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", m.RepoURL),
398			})
399			return issues
400		}
401		if !strings.EqualFold(got, m.BinarySHA256) {
402			issues = append(issues, PluginDoctorIssue{
403				Plugin:  m.Name,
404				Problem: "managed binary no longer matches the digest recorded at install; it was modified or replaced outside entire",
405				Fix:     fmt.Sprintf("reinstall from the recorded source: entire plugin install %s --force", m.RepoURL),
406			})
407		}
408		return issues
409	}
410	
411	// quarantinedPath returns the path to flag when the file (or its symlink
412	// target) carries com.apple.quarantine. Best-effort, macOS only; any error
413	// means "not quarantined". The attribute appears when a user manually
414	// drops a browser-downloaded binary into the managed dir — CLI downloads
415	// don't set it.
416	//
417	// Checking the bin entry is sufficient even though remote installs link
418	// bin/entire-<name> to the real binary under pkg/: macOS xattr follows
419	// symlinks by default (-s is the flag to act on the link itself), so both
420	// the probe here and the suggested `xattr -d` fix operate on the target.
421	func quarantinedPath(ctx context.Context, path string) string {
422		if runtime.GOOS != darwinGOOS {
423			return ""
424		}
425		out, err := exec.CommandContext(ctx, "xattr", "-p", "com.apple.quarantine", path).Output()
426		if err != nil || strings.TrimSpace(string(out)) == "" {
427			return ""
428		}
429		return path
430	}
