1	package cli
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"runtime"
12		"strings"
13		"time"
14	
15		"golang.org/x/mod/semver"
16	)
17	
18	// Remote install orchestration: resolve tag → fetch metadata → download +
19	// verify + extract → place under pkg/<name>/ → link into bin/ → write
20	// manifest. The bin/ link goes through the same InstallPluginFromPath used
21	// by local-dev installs, so conflict handling, atomic replace, and the
22	// Windows symlink fallbacks are shared, not duplicated.
23	
24	// maxTagFallbacks bounds how many tags we walk down when the newest tag has
25	// no published assets (tag pushed, release not finished).
26	const maxTagFallbacks = 3
27	
28	// RemoteInstallOptions configures InstallPluginFromRepo.
29	type RemoteInstallOptions struct {
30		// RepoURL is the full git URL of the plugin repository.
31		RepoURL string
32		// Pin, when non-empty, installs exactly this tag and marks the
33		// manifest pinned so upgrade skips it.
34		Pin string
35		// Force replaces an existing managed entry with the same name.
36		Force bool
37		// AllowUnverified permits installing a release that publishes no
38		// checksums.txt covering this platform. Off by default: downloading and
39		// executing an unauthenticated binary is the supply-chain risk the
40		// checksum path exists to remove, so it takes an explicit opt-in.
41		AllowUnverified bool
42	}
43	
44	// RemoteInstallResult is what a successful remote install produced.
45	type RemoteInstallResult struct {
46		Installed *InstalledPlugin
47		Manifest  *PluginManifest
48		Metadata  *PluginMetadata
49		// SkippedTags lists newer tags that were passed over for missing
50		// assets, newest first. Callers surface these as warnings.
51		SkippedTags []string
52	}
53	
54	// InstallPluginFromRepo installs a plugin from a git repository URL.
55	// Dependency resolution deliberately does not happen here — callers
56	// (the install command) plan and confirm dependency installs first.
57	func InstallPluginFromRepo(ctx context.Context, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
58		repoURL := strings.TrimRight(opts.RepoURL, "/")
59	
60		var tags []string
61		if opts.Pin != "" {
62			tags = []string{opts.Pin}
63		} else {
64			var err error
65			tags, err = listRemoteSemverTags(ctx, repoURL)
66			if err != nil {
67				return nil, err
68			}
69			if len(tags) == 0 {
70				return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
71			}
72			if len(tags) > maxTagFallbacks {
73				tags = tags[:maxTagFallbacks]
74			}
75		}
76	
77		var lastErr error
78		for i, tag := range tags {
79			res, err := installRepoAtTag(ctx, repoURL, tag, opts)
80			if err == nil {
81				res.SkippedTags = tags[:i]
82				return res, nil
83			}
84			lastErr = err
85			if !errors.Is(err, errAssetNotFound) {
86				return nil, err
87			}
88		}
89		return nil, lastErr
90	}
91	
92	func installRepoAtTag(ctx context.Context, repoURL, tag string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
93		meta, err := fetchPluginMetadataAtTag(ctx, repoURL, tag)
94		if err != nil {
95			return nil, err
96		}
97		var name string
98		if meta != nil && meta.Name != "" {
99			name = meta.Name
100		} else if name, err = pluginNameFromRepoURL(repoURL); err != nil {
101			return nil, err
102		}
103	
104		if existing, err := FindInstalledPlugin(name); err != nil {
105			return nil, err
106		} else if existing != nil && !opts.Force {
107			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", name, existing.Path)
108		}
109	
110		staging, err := os.MkdirTemp("", "entire-plugin-fetch-")
111		if err != nil {
112			return nil, fmt.Errorf("create staging dir: %w", err)
113		}
114		defer os.RemoveAll(staging)
115	
116		asset, err := downloadPluginAsset(ctx, meta, repoURL, name, tag, staging, opts.AllowUnverified)
117		if err != nil {
118			return nil, err
119		}
120	
121		binBase := pluginBinaryName(name)
122		stagedBin := filepath.Join(staging, "extracted-"+binBase)
123		if err := extractPluginBinary(asset.Path, name, stagedBin); err != nil {
124			return nil, err
125		}
126	
127		pkgDir, err := EnsurePluginPkgDir(name)
128		if err != nil {
129			return nil, err
130		}
131		sweepOldBinaries(pkgDir)
132		pkgBin := filepath.Join(pkgDir, binBase)
133		if err := replaceBinary(stagedBin, pkgBin); err != nil {
134			return nil, fmt.Errorf("place plugin binary: %w", err)
135		}
136	
137		// Digest the binary we actually placed, not just the archive it came from.
138		// asset.SHA256 covers the downloaded asset, which is discarded with the
139		// staging dir — so it records provenance but can never detect later
140		// tampering. binDigest is what `plugin doctor` re-checks.
141		binDigest, err := fileSHA256(pkgBin)
142		if err != nil {
143			return nil, fmt.Errorf("hash installed plugin binary: %w", err)
144		}
145	
146		installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
147		if err != nil {
148			return nil, err
149		}
150	
151		manifest := &PluginManifest{
152			Name:         name,
153			RepoURL:      repoURL,
154			Tag:          tag,
155			Asset:        asset.Asset,
156			SHA256:       asset.SHA256,
157			BinarySHA256: binDigest,
158			Unverified:   !asset.Verified,
159			Pinned:       opts.Pin != "",
160			InstalledAt:  time.Now().UTC(),
161		}
162		if meta != nil {
163			manifest.Requires = meta.Requires
164		}
165		if err := SavePluginManifest(manifest); err != nil {
166			return nil, err
167		}
168		return &RemoteInstallResult{Installed: installed, Manifest: manifest, Metadata: meta}, nil
169	}
170	
171	// UpgradeOutcome describes what UpgradeInstalledPlugin did.
172	type UpgradeOutcome struct {
173		Name string
174		// Pinned: skipped because the manifest is pinned.
175		Pinned bool
176		// UpToDate: already at the newest tag.
177		UpToDate bool
178		// FromTag/ToTag are set when an upgrade actually happened.
179		FromTag, ToTag string
180	}
181	
182	// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
183	// plugin and reinstalls when it differs from the manifest's tag. Plugins
184	// without a manifest (local-dev symlinks) are not upgradable.
185	func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
186		m, err := LoadPluginManifest(name)
187		if err != nil {
188			return nil, err
189		}
190		if m == nil {
191			return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
192		}
193		if m.Pinned {
194			return &UpgradeOutcome{Name: name, Pinned: true}, nil
195		}
196		tags, err := listRemoteSemverTags(ctx, m.RepoURL)
197		if err != nil {
198			return nil, err
199		}
200		if len(tags) == 0 {
201			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
202		}
203		// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
204		// same version, and a remote that re-tagged with the other spelling
205		// must not trigger a reinstall.
206		if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
207			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
208		}
209		// Inherit the install-time trust decision: a plugin the user knowingly
210		// installed unverified shouldn't start failing on upgrade, and one
211		// installed verified must not silently downgrade to unverified.
212		res, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
213			RepoURL: m.RepoURL, Force: true, AllowUnverified: m.Unverified,
214		})
215		if err != nil {
216			return nil, err
217		}
218		// The install may have fallen back past an asset-less newest tag and
219		// landed on the version already installed — that's up-to-date, not an
220		// upgrade line claiming X → X.
221		if semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(m.Tag)) <= 0 {
222			return &UpgradeOutcome{Name: name, UpToDate: true}, nil
223		}
224		return &UpgradeOutcome{Name: name, FromTag: m.Tag, ToTag: res.Manifest.Tag}, nil
225	}
226	
227	// replaceBinary moves src over dest atomically. On Windows, a running
228	// executable can't be replaced (sharing violation) but it *can* be renamed:
229	// move the old binary aside to a .old-<rand> file and retry; leftovers are
230	// swept on the next install. os.Rename fails across filesystems (staging is
231	// in the system temp dir), so a copy fallback covers that case.
232	func replaceBinary(src, dest string) error {
233		err := os.Rename(src, dest)
234		if err == nil {
235			return nil
236		}
237		if runtime.GOOS == windowsGOOS {
238			if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
239				if err = os.Rename(src, dest); err == nil {
240					return nil
241				}
242			}
243		}
244		// Cross-device rename: copy + fsync-free write, then remove src.
245		in, openErr := os.Open(src) //nolint:gosec // staging file we created
246		if openErr != nil {
247			return errors.Join(err, openErr)
248		}
249		defer in.Close()
250		if writeErr := writeExecutable(in, dest); writeErr != nil {
251			return errors.Join(err, writeErr)
252		}
253		_ = os.Remove(src)
254		return nil
255	}
256	
257	// oldBinaryAsidePath returns a unique .old- sibling path for the
258	// rename-aside trick. Random suffix so concurrent upgrades can't collide.
259	func oldBinaryAsidePath(dest string) string {
260		var b [4]byte
261		if _, err := rand.Read(b[:]); err != nil {
262			return dest + ".old-fallback"
263		}
264		return dest + ".old-" + hex.EncodeToString(b[:])
265	}
266	
267	// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
268	// rename-aside fallback. Failures are ignored — the files are inert.
269	func sweepOldBinaries(pkgDir string) {
270		entries, err := os.ReadDir(pkgDir)
271		if err != nil {
272			return
273		}
274		for _, e := range entries {
275			if strings.Contains(e.Name(), ".old-") {
276				_ = os.Remove(filepath.Join(pkgDir, e.Name()))
277			}
278		}
279	}
280	
281	// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
282	// The dependency guard lives in the command layer so --force can bypass it.
283	func RemoveManagedPlugin(name string) error {
284		if err := RemoveInstalledPlugin(name); err != nil {
285			return err
286		}
287		return RemovePluginPkg(name)
288	}
