1	package cli
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"runtime"
11		"sort"
12		"time"
13	
14		"gopkg.in/yaml.v3"
15	)
16	
17	// Managed-install manifests. A plugin installed from a remote repository
18	// gets a per-plugin home under the managed dir:
19	//
20	//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
21	//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
22	//
23	// The bin/ dir remains the only dispatch surface — pkg/ binaries are
24	// linked into bin/ via the same symlink→hardlink→copy fallback as local
25	// installs, so the kubectl-style resolver in plugin.go never changes.
26	//
27	// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
28	// and have no manifest; ListPluginManifests simply doesn't see them.
29	const (
30		pluginManagedPkgSubdir = "pkg"
31		pluginManifestFileName = "manifest.yml"
32		// windowsExeExt is the extension Windows executables need.
33		windowsExeExt = ".exe"
34	)
35	
36	// pluginBinaryName returns the on-disk executable name for a bare plugin
37	// name: entire-<name>, plus the Windows extension where the host needs it.
38	func pluginBinaryName(name string) string {
39		if runtime.GOOS == windowsGOOS {
40			return pluginBinaryPrefix + name + windowsExeExt
41		}
42		return pluginBinaryPrefix + name
43	}
44	
45	// PluginManifest records how a managed plugin was installed. Settings
46	// configure behavior; manifests record facts. The dependency list is
47	// copied from the plugin's metadata at install time so reverse-dependency
48	// checks (remove guard, doctor) work offline.
49	type PluginManifest struct {
50		// Name is the bare plugin name ("run" for entire-run).
51		Name string `yaml:"name"`
52		// RepoURL is the full git URL the plugin was installed from.
53		RepoURL string `yaml:"repo_url"`
54		// Tag is the git tag that was installed (e.g. "v0.2.1").
55		Tag string `yaml:"tag"`
56		// Asset is the release asset filename the binary came from. Empty for
57		// raw-binary downloads where the asset name equals the binary name.
58		Asset string `yaml:"asset,omitempty"`
59		// SHA256 is the hex digest of the downloaded asset.
60		SHA256 string `yaml:"sha256,omitempty"`
61		// BinarySHA256 is the hex digest of the installed binary under
62		// pkg/<name>/. Distinct from SHA256, which covers the downloaded asset —
63		// usually an archive, and discarded with the staging dir. Recording the
64		// binary is what lets `plugin doctor` detect post-install tampering.
65		BinarySHA256 string `yaml:"binary_sha256,omitempty"`
66		// Unverified records that no checksum manifest authenticated the
67		// download (installed with --allow-unverified). Surfaced by doctor.
68		Unverified bool `yaml:"unverified,omitempty"`
69		// Pinned marks installs done with --pin; upgrade skips them.
70		Pinned bool `yaml:"pinned,omitempty"`
71		// InstalledAt is when the install (or last upgrade) completed.
72		InstalledAt time.Time `yaml:"installed_at,omitempty"`
73		// Requires is the dependency list from the plugin's entire-plugin.yml
74		// at the installed tag.
75		Requires []PluginRequirement `yaml:"requires,omitempty"`
76	}
77	
78	// PluginRequirement declares a dependency on another plugin. Shared between
79	// the author-side metadata file (entire-plugin.yml) and the install-side
80	// manifest so the two can never drift.
81	type PluginRequirement struct {
82		// Name is the bare plugin name of the dependency.
83		Name string `yaml:"name"`
84		// RepoURL is where to install the dependency from when it's missing.
85		// Optional when the dependency is resolvable through the index.
86		RepoURL string `yaml:"repo_url,omitempty"`
87		// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
88		// only — there is deliberately no range syntax.
89		MinVersion string `yaml:"min_version,omitempty"`
90	}
91	
92	// PluginMetadata is the author-side declaration committed at the root of a
93	// plugin repository as entire-plugin.yml. Everything is optional — a repo
94	// without the file installs fine; the name then derives from the repo URL.
95	type PluginMetadata struct {
96		// Name is the bare plugin name. When empty, derived from the repo URL
97		// basename (entire-run → run).
98		Name string `yaml:"name,omitempty"`
99		// Description is a one-line summary shown by info/search.
100		Description string `yaml:"description,omitempty"`
101		// DownloadURL overrides the per-forge release-asset URL convention.
102		// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
103		// When {asset} is present, candidate asset filenames are substituted;
104		// otherwise the expanded template is fetched as-is.
105		DownloadURL string `yaml:"download_url,omitempty"`
106		// Requires lists plugins this plugin needs at runtime.
107		Requires []PluginRequirement `yaml:"requires,omitempty"`
108	}
109	
110	// pluginMetadataFileName is the well-known path of the author-side metadata
111	// file at the root of a plugin repository.
112	const pluginMetadataFileName = "entire-plugin.yml"
113	
114	// ParsePluginMetadata decodes entire-plugin.yml content. Strict decoding:
115	// unknown keys are an error, surfacing author typos at install time rather
116	// than silently ignoring a misspelled "requires".
117	func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
118		var meta PluginMetadata
119		dec := yaml.NewDecoder(bytes.NewReader(data))
120		dec.KnownFields(true)
121		if err := dec.Decode(&meta); err != nil {
122			// An empty or comment-only stream decodes to io.EOF. The file is
123			// documented as optional and a *missing* one is fine, so a committed
124			// placeholder must not be fatal at every tag. An explicit "---" already
125			// behaved this way; align the empty cases with it.
126			if !errors.Is(err, io.EOF) {
127				return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
128			}
129			meta = PluginMetadata{}
130		}
131		if meta.Name != "" {
132			if err := validatePluginName(meta.Name); err != nil {
133				return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
134			}
135		}
136		for _, req := range meta.Requires {
137			if err := validatePluginName(req.Name); err != nil {
138				return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
139			}
140			// A requirement's repo_url is author-controlled and reaches the git
141			// CLI during dependency planning — which runs before the install
142			// confirmation prompt. Reject non-URLs at the parse boundary.
143			if req.RepoURL != "" {
144				if err := validatePluginRepoURL(req.RepoURL); err != nil {
145					return nil, fmt.Errorf("%s declares invalid repo_url for requirement %q: %w", pluginMetadataFileName, req.Name, err)
146				}
147			}
148		}
149		return &meta, nil
150	}
151	
152	// PluginPkgDir returns the per-plugin package directory for the given bare
153	// name. Not created — callers use EnsurePluginPkgDir when writing.
154	func PluginPkgDir(name string) (string, error) {
155		if err := validatePluginName(name); err != nil {
156			return "", err
157		}
158		parent, err := pluginParentDir()
159		if err != nil {
160			return "", err
161		}
162		return filepath.Join(parent, pluginManagedPkgSubdir, name), nil
163	}
164	
165	// EnsurePluginPkgDir creates the package directory for name.
166	func EnsurePluginPkgDir(name string) (string, error) {
167		dir, err := PluginPkgDir(name)
168		if err != nil {
169			return "", err
170		}
171		if err := os.MkdirAll(dir, 0o750); err != nil {
172			return "", fmt.Errorf("create plugin pkg dir: %w", err)
173		}
174		return dir, nil
175	}
176	
177	// LoadPluginManifest reads the manifest for name. Returns (nil, nil) when
178	// the plugin has no manifest — local-dev installs and raw-PATH plugins.
179	func LoadPluginManifest(name string) (*PluginManifest, error) {
180		dir, err := PluginPkgDir(name)
181		if err != nil {
182			return nil, err
183		}
184		data, err := os.ReadFile(filepath.Join(dir, pluginManifestFileName)) //nolint:gosec // path is inside the managed pkg tree
185		if err != nil {
186			if errors.Is(err, os.ErrNotExist) {
187				return nil, nil //nolint:nilnil // no-manifest signal
188			}
189			return nil, fmt.Errorf("read plugin manifest: %w", err)
190		}
191		var m PluginManifest
192		if err := yaml.Unmarshal(data, &m); err != nil {
193			return nil, fmt.Errorf("parse plugin manifest for %q: %w", name, err)
194		}
195		return &m, nil
196	}
197	
198	// SavePluginManifest writes the manifest into the plugin's pkg dir.
199	func SavePluginManifest(m *PluginManifest) error {
200		// Strip any credentials before persisting: manifest.yml is mode 0644 and a
201		// token in a remote URL has no business on disk. Upgrades re-resolve the
202		// remote through git's credential helpers, which is where auth belongs.
203		m.RepoURL = redactURL(m.RepoURL)
204		for i := range m.Requires {
205			m.Requires[i].RepoURL = redactURL(m.Requires[i].RepoURL)
206		}
207		dir, err := EnsurePluginPkgDir(m.Name)
208		if err != nil {
209			return err
210		}
211		data, err := yaml.Marshal(m)
212		if err != nil {
213			return fmt.Errorf("marshal plugin manifest: %w", err)
214		}
215		path := filepath.Join(dir, pluginManifestFileName)
216		if err := os.WriteFile(path, data, 0o644); err != nil { //nolint:gosec // manifest is non-secret provenance metadata
217			return fmt.Errorf("write plugin manifest: %w", err)
218		}
219		return nil
220	}
221	
222	// ListPluginManifests returns the manifests of every remote-installed
223	// plugin, sorted by name. Pkg entries without a readable manifest are
224	// skipped — a half-removed plugin shouldn't break listing.
225	func ListPluginManifests() ([]*PluginManifest, error) {
226		parent, err := pluginParentDir()
227		if err != nil {
228			return nil, err
229		}
230		entries, err := os.ReadDir(filepath.Join(parent, pluginManagedPkgSubdir))
231		if err != nil {
232			if errors.Is(err, os.ErrNotExist) {
233				return nil, nil
234			}
235			return nil, fmt.Errorf("read plugin pkg dir: %w", err)
236		}
237		var out []*PluginManifest
238		for _, e := range entries {
239			if !e.IsDir() {
240				continue
241			}
242			m, err := LoadPluginManifest(e.Name())
243			if err != nil || m == nil {
244				continue
245			}
246			out = append(out, m)
247		}
248		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
249		return out, nil
250	}
251	
252	// RemovePluginPkg deletes the plugin's pkg dir (binary + manifest).
253	// Missing dir is not an error — local-dev installs never had one.
254	func RemovePluginPkg(name string) error {
255		dir, err := PluginPkgDir(name)
256		if err != nil {
257			return err
258		}
259		if err := os.RemoveAll(dir); err != nil {
260			return fmt.Errorf("remove plugin pkg dir: %w", err)
261		}
262		return nil
263	}
