1	package cli
2	
3	import (
4		"context"
5		"os"
6		"os/exec"
7		"path/filepath"
8		"strings"
9		"testing"
10	
11		"github.com/entireio/cli/cmd/entire/cli/testutil"
12	)
13	
14	// newTaggedPluginRepo creates a git repo with entire-plugin.yml (when
15	// metadata is non-empty) and the given tags, returning its file:// URL.
16	// file:// (not a bare path) forces git's transport machinery, matching how
17	// a real remote behaves for ls-remote and shallow clones.
18	func newTaggedPluginRepo(t *testing.T, metadata string, tags ...string) string {
19		t.Helper()
20		dir := t.TempDir()
21		testutil.InitRepo(t, dir)
22		if metadata != "" {
23			testutil.WriteFile(t, dir, pluginMetadataFileName, metadata)
24			testutil.GitAdd(t, dir, pluginMetadataFileName)
25		} else {
26			testutil.WriteFile(t, dir, "README.md", "readme")
27			testutil.GitAdd(t, dir, "README.md")
28		}
29		testutil.GitCommit(t, dir, "init")
30		for _, tag := range tags {
31			if out, err := exec.CommandContext(t.Context(), "git", "-C", dir, "tag", tag).CombinedOutput(); err != nil {
32				t.Fatalf("git tag %s: %v: %s", tag, err, out)
33			}
34		}
35		return "file://" + filepath.ToSlash(dir)
36	}
37	
38	func TestListRemoteSemverTags(t *testing.T) {
39		t.Parallel()
40		url := newTaggedPluginRepo(t, "", "v0.1.0", "v0.10.0", "v0.2.0", "not-a-version", "1.0.0")
41		tags, err := listRemoteSemverTags(context.Background(), url)
42		if err != nil {
43			t.Fatalf("listRemoteSemverTags: %v", err)
44		}
45		// Bare "1.0.0" is valid semver (canonicalized); "not-a-version" is dropped.
46		want := []string{"1.0.0", "v0.10.0", "v0.2.0", "v0.1.0"}
47		if len(tags) != len(want) {
48			t.Fatalf("tags = %v, want %v", tags, want)
49		}
50		for i := range want {
51			if tags[i] != want[i] {
52				t.Errorf("tags[%d] = %q, want %q (full: %v)", i, tags[i], want[i], tags)
53			}
54		}
55	}
56	
57	func TestListRemoteSemverTags_BadRemote(t *testing.T) {
